/**
 * Guest QR codes (Stage 4.4). A QR code encodes `<guest-base-url>/a/<token>` (ADR-012); the token
 * is generated by the database (`create_qr_code`, 256-bit base64url) and never by clients.
 */
import { z } from 'zod';

/** Same rule as the `qr_codes.token` check constraint. */
export const QR_TOKEN_PATTERN = /^[A-Za-z0-9_-]{22,64}$/;

export const qrLabelSchema = z.preprocess(
  (v) => (typeof v === 'string' ? v.trim() : v),
  z.string().max(80, { message: 'TOO_LONG' }),
);

const LOCAL_HOSTS = new Set(['localhost', '127.0.0.1', '[::1]']);

/**
 * Validates the guest app base URL: https only, except plain http on a local host for
 * development. Returns the normalised base without a trailing slash, or null.
 */
export function parseGuestBaseUrl(value: string | undefined): string | null {
  if (!value) return null;
  let url: URL;
  try {
    url = new URL(value);
  } catch {
    return null;
  }
  const local = LOCAL_HOSTS.has(url.hostname);
  if (url.protocol !== 'https:' && !(url.protocol === 'http:' && local)) return null;
  if (url.username || url.password || url.search || url.hash) return null;
  return `${url.origin}${url.pathname.replace(/\/+$/, '')}`;
}

/** The URL printed in a QR code. Throws on an invalid base or token (never encode junk). */
export function guestQrUrl(baseUrl: string, token: string): string {
  const base = parseGuestBaseUrl(baseUrl);
  if (!base) throw new Error('Invalid guest base URL');
  if (!QR_TOKEN_PATTERN.test(token)) throw new Error('Invalid QR token');
  return `${base}/a/${token}`;
}

/** File name for downloads, e.g. `nookscanner-qr-marina-view-front-door.svg`. */
export function qrFileName(apartmentName: string, label: string | null, ext: 'svg' | 'png') {
  const part = (s: string) =>
    s
      .normalize('NFKD')
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-+|-+$/g, '')
      .slice(0, 40);
  const name = [part(apartmentName), label ? part(label) : ''].filter(Boolean).join('-');
  return `nookscanner-qr${name ? `-${name}` : ''}.${ext}`;
}
